pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // Ensure at least one recipient and a valid address for caddress
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        // Ensure each recipient is non-zero to avoid trivial reverts
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Ensure the call address is not the contract itself to avoid reentrancy oddities
        vm.assume(caddress != address(c));
        // Bound v to avoid overflow issues (optional, but safe)
        v = bound(v, 0, 1e30);
        // Call transfer and check that it returns true
        bool result = c.transfer(from, caddress, _tos, v);
        assertTrue(result, "transfer should return true");
    }
}

