import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // bound v to a reasonable range for transfer
        v = bound(v, 1, 1e18);
        // ensure _tos is non-empty as required by require
        vm.assume(_tos.length > 0);
        // call transfer, which either reverts or returns true
        bool result = c.transfer(from, caddress, _tos, v);
        assertTrue(result == true);
    }
}

