pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);
        bool selfTransfer = false;
        for (uint i = 0; i < tos.length; i++) {
            if (tos[i] == from) {
                selfTransfer = true;
                break;
            }
        }
        vm.assume(selfTransfer);
        bool success = c.transfer(from, caddress, tos, v);
        assertTrue(success);
    }
}

