pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint256 v) public {
        // Assume non-empty array to avoid require(false)
        vm.assume(tos.length > 0);
        // Record caller's balance before call
        uint256 balanceBefore = address(this).balance;
        // Call transfer
        bool success = c.transfer(from, caddress, tos, v);
        // Rule: transfer should always return true and the caller's balance unchanged
        assertTrue(success && address(this).balance == balanceBefore);
    }
}

